int main(void)
{
  int n, a, b, c;
  for (n = 100; n <= 999; n++) {
    a = n / 100;
    b = n / 10 % 10;
    c = n % 10;
    if (a * a * a + b * b * b + c * c * c == n)
      printf("%d ", n);
  }
  printf("\n");
  return 0;
}
